34:    *    new AssignmentNode(new SymbolNode('a'), new ConstantNode(2));                      // a=2
35:    *    new AssignmentNode(new SymbolNode('a'), new IndexNode('b'), new ConstantNode(2))   // a.b=2
36:    *    new AssignmentNode(new SymbolNode('a'), new IndexNode(1, 2), new ConstantNode(3))  // a[1,2]=3
37:    *
38:    * @param {SymbolNode | AccessorNode} object  Object on which to assign a value
39:    * @param {IndexNode} [index=null]            Index, property name or matrix
40:    *                                            index. Optional. If not provided
