43:    *                                            global scope.
44:    * @param {Node} value                        The value to be assigned
45:    */
46:   function AssignmentNode(object, index, value) {
47:     if (!(this instanceof AssignmentNode)) {
48:       throw new SyntaxError('Constructor must be called with the new operator');
49:     }
50: 
51:     this.object = object;
52:     this.index = value ? index : null;
53:     this.value = value ? value : index;
54: 
55:     // validate input
56:     if (!object || !(object.isSymbolNode || object.isAccessorNode)) {
