58:     }
59:     if (object && object.isSymbolNode && object.name === 'end') {
60:       throw new Error('Cannot assign to symbol "end"');
61:     }
62:     if (this.index && !this.index.isIndexNode) {
63:       throw new TypeError('IndexNode expected as "index"');
64:     }
65:     if (!this.value || !this.value.isNode) {
66:       throw new TypeError('Node expected as "value"');
67:     }
