128:       return 'setSafeProperty(' + object + ', ' + jsProp + ', ' + value + ')';
129:     }
130:     else if (node.object.isSymbolNode) {
131:       // update a matrix subset, for example `a[2]=3`
132:       size = node.index.needsSize() ? 'var size = math.size(object).valueOf();' : '';
