198:    * Create a new AssignmentNode having it's childs be the results of calling
199:    * the provided callback function for each of the childs of the original node.
200:    * @param {function(child: Node, path: string, parent: Node): Node} callback
201:    * @returns {AssignmentNode} Returns a transformed copy of the node
202:    */
203:   AssignmentNode.prototype.map = function (callback) {
204:     var object = this._ifNode(callback(this.object, 'object', this));
205:     var index = this.index
206:         ? this._ifNode(callback(this.index, 'index', this))
207:         : null;
208:     var value = this._ifNode(callback(this.value, 'value', this));
209: 
210:     return new AssignmentNode(object, index, value);
211:   };
