221:   /*
222:    * Is parenthesis needed?
223:    * @param {node} node
224:    * @param {string} [parenthesis='keep']
225:    * @private
226:    */
227:   function needParenthesis(node, parenthesis) {
228:     if (!parenthesis) {
229:       parenthesis = 'keep';
230:     }
231: 
232:     var precedence = operators.getPrecedence(node, parenthesis);
233:     var exprPrecedence = operators.getPrecedence(node.value, parenthesis);
234:     return (parenthesis === 'all')
235:       || ((exprPrecedence !== null) && (exprPrecedence <= precedence));
236:   }
237: 
238:   /**
239:    * Get string representation
240:    * @param {Object} options
241:    * @return {string}
242:    */
243:   AssignmentNode.prototype._toString = function(options) {
244:     var object = this.object.toString(options);
245:     var index = this.index ? this.index.toString(options) : '';
246:     var value = this.value.toString(options);
247:     if (needParenthesis(this, options && options.parenthesis)) {
248:       value = '(' + value + ')';
249:     }
250: 
251:     return object + index + ' = ' + value;
252:   };
253: 
254:   /**
255:    * Get LaTeX representation
256:    * @param {Object} options
257:    * @return {string}
258:    */
259:   AssignmentNode.prototype._toTex = function(options) {
260:     var object = this.object.toTex(options);
261:     var index = this.index ? this.index.toTex(options) : '';
262:     var value = this.value.toTex(options);
263:     if (needParenthesis(this, options && options.parenthesis)) {
264:       value = '\\left(' + value + '\\right)';
265:     }
266: 
267:     return object + index + ':=' + value;
268:   };
269: 
270:   return AssignmentNode;
